 const observer='IntersectionObserver'in window?new IntersectionObserver(es=>{visible=es[0].isIntersecting;sync()},{threshold:.08}):null;if(observer)observer.observe(root);else visible=true;
 on(root,'focusin',sync);on(root,'focusout',()=>queueMicrotask(sync));on(mobile,'change',()=>{stop();const first=indices[0];indices=[first,(first+1)%items.length,(first+2)%items.length];render();sync()});on(reduced,'change',sync);if(connection?.addEventListener)on(connection,'change',sync);on(document,'visibilitychange',sync);on(window,'pagehide',()=>{pageHidden=true;sync()});on(window,'pageshow',()=>{pageHidden=false;sync()});sync();
