 const script=document.currentScript,base=new URL('.',script?.src||'https://doctorleegh-debug.github.io/bbx-layered-lifting/shared/brand-20261005/brand-refresh.js').href;
 const locale=(()=>{const h=location.hostname;if(h.includes('beautyblossomth'))return'TH';for(const c of ['EN','JP','CN','TW','HK'])if(h.startsWith(c.toLowerCase()+'.'))return c;return script?.dataset.locale||'KO'})();
